import{_ as a,c as s,o as i,aj as t,ak as n}from"./chunks/framework.CIIM_L32.js";const m=JSON.parse('{"title":"FAQ","description":"Torch-RecHub frequently asked questions and troubleshooting guide","frontmatter":{"title":"FAQ","description":"Torch-RecHub frequently asked questions and troubleshooting guide"},"headers":[],"relativePath":"community/faq.md","filePath":"en/community/faq.md"}'),o={name:"community/faq.md"};function r(l,e,h,d,p,c){return i(),s("div",null,[...e[0]||(e[0]=[t('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to “FAQ”">​</a></h1><p>Frequently asked questions and troubleshooting guidance for Torch-RecHub.</p><h2 id="will-there-be-a-tensorflow-version" tabindex="-1">Will there be a TensorFlow version? <a class="header-anchor" href="#will-there-be-a-tensorflow-version" aria-label="Permalink to “Will there be a TensorFlow version?”">​</a></h2><p>There are no current plans for one. PyTorch is the project&#39;s only runtime, and the focus is on recommendation-model implementations that are easy to learn and extend.</p><h2 id="why-is-the-example-auc-low-or-unstable" tabindex="-1">Why is the example AUC low or unstable? <a class="header-anchor" href="#why-is-the-example-auc-low-or-unstable" aria-label="Permalink to “Why is the example AUC low or unstable?”">​</a></h2><p>The sample datasets under <code>examples/</code> are intentionally small and only validate data formats, feature definitions, and the training path. They are not intended for model-quality comparisons. Download the complete datasets linked from the README and create proper train, validation, and test splits before comparing models.</p><h2 id="what-should-i-do-if-annoy-fails-to-install-on-windows" tabindex="-1">What should I do if Annoy fails to install on Windows? <a class="header-anchor" href="#what-should-i-do-if-annoy-fails-to-install-on-windows" aria-label="Permalink to “What should I do if Annoy fails to install on Windows?”">​</a></h2><p>Install the Annoy extra declared by the project:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;torch-rechub[annoy]&quot;</span></span></code></pre></div><p>If pip cannot find a wheel for the current Python version and platform, it builds Annoy from source. When Windows reports <code>Microsoft Visual C++ 14.0 or greater is required</code>, install <a href="https://visualstudio.microsoft.com/visual-cpp-build-tools/" target="_blank" rel="noreferrer">Microsoft C++ Build Tools</a>, reopen the terminal, and rerun the command. Do not install an old wheel built for a different Python version.</p><p><img src="'+n+`" alt="Annoy build environment error" title="Annoy build environment error"></p><h2 id="why-does-torch-rechub-serving-still-fail-to-import-after-installing-one-vector-backend" tabindex="-1">Why does <code>torch_rechub.serving</code> still fail to import after installing one vector backend? <a class="header-anchor" href="#why-does-torch-rechub-serving-still-fail-to-import-after-installing-one-vector-backend" aria-label="Permalink to “Why does torch_rechub.serving still fail to import after installing one vector backend?”">​</a></h2><p>The current <code>torch_rechub.serving</code> package imports the Annoy, Faiss, and Milvus implementations together. Install all three extras when using the unified <code>builder_factory</code> entry point:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;torch-rechub[annoy,faiss,milvus]&quot;</span></span></code></pre></div><h2 id="why-does-fit-report-that-the-model-save-path-does-not-exist" tabindex="-1">Why does <code>fit()</code> report that the model save path does not exist? <a class="header-anchor" href="#why-does-fit-report-that-the-model-save-path-does-not-exist" aria-label="Permalink to “Why does fit() report that the model save path does not exist?”">​</a></h2><p>Trainers do not create <code>model_path</code> automatically. Create it before training:</p><div class="language-python"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> os</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> torch_rechub.trainers </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> CTRTrainer</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">os.makedirs(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;saved/deepfm&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">exist_ok</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">True</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">trainer </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> CTRTrainer(model, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">model_path</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;saved/deepfm&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">trainer.fit(train_dataloader, val_dataloader)</span></span></code></pre></div><h2 id="why-does-an-example-fail-to-find-its-data-when-run-from-another-directory" tabindex="-1">Why does an example fail to find its data when run from another directory? <a class="header-anchor" href="#why-does-an-example-fail-to-find-its-data-when-run-from-another-directory" aria-label="Permalink to “Why does an example fail to find its data when run from another directory?”">​</a></h2><p>Some historical examples use data paths relative to the script directory. Change into the relevant <code>examples/ranking</code>, <code>examples/matching</code>, or other example directory first. When a script exposes the option, you can instead pass an explicit path with <code>--dataset_path</code>.</p><h2 id="can-the-same-feature-objects-be-passed-to-multiple-models" tabindex="-1">Can the same Feature objects be passed to multiple models? <a class="header-anchor" href="#can-the-same-feature-objects-be-passed-to-multiple-models" aria-label="Permalink to “Can the same Feature objects be passed to multiple models?”">​</a></h2><p>This is not recommended. <code>SparseFeature</code> and <code>SequenceFeature</code> cache their created embeddings, so reusing the same Feature instance makes multiple models share parameters. See <a href="/torch-rechub/core/features.html#feature-instances-and-embedding-ownership">Feature Instances and Embedding Ownership</a>.</p>`,21)])])}const u=a(o,[["render",r]]);export{m as __pageData,u as default};
